'use client'

import { useEffect, useState } from 'react'
import gsap from 'gsap'
import { createTransition } from './transition-core'
import { BurnArt, type BurnOrigin } from './burn-art'
import './transitions.css'

export type FilmBurnOptions = {
  /** Where the fire starts. 'random' picks a fresh corner on every navigation. */
  origin: BurnOrigin | 'random'
  /** Multiplies the whole timeline. Above 1 is faster. */
  speed: number
  /** Seconds the fire takes to consume the page. */
  burn: number
  /** Seconds the char takes to burn away again, revealing the new page. */
  reveal: number
  /** How far the ember edge is chewed up. 0 is a clean circle. */
  turbulence: number
}

const DEFAULTS: FilmBurnOptions = {
  origin: 'random',
  speed: 1,
  burn: 0.62,
  reveal: 0.5,
  turbulence: 78,
}

const CORNERS: BurnOrigin[] = ['top-left', 'top-right', 'bottom-left', 'bottom-right']
const pickCorner = () => CORNERS[Math.floor(Math.random() * CORNERS.length)]

type State = {
  /** How far the front has travelled. */
  burn: number
  /** 'cover' eats the page; 'clear' eats the char away again. */
  mode: 'cover' | 'clear'
  origin: BurnOrigin
  /** Kept mounted at rest so the filter is already warm — see below. */
  live: boolean
}

const REST: State = { burn: 0, mode: 'cover', origin: 'bottom-right', live: false }

/**
 * The overlay renders from a handful of values, so the phases only have to
 * drive those. A module-level setter is enough of a bridge — the overlay mounts
 * once and there is never more than one navigation in flight.
 */
let push: ((v: State) => void) | null = null

function BurnOverlay({ options }: { options: FilmBurnOptions }) {
  const [v, setV] = useState<State>(REST)
  useEffect(() => {
    push = setV
    return () => {
      push = null
    }
  }, [])

  /*
   * Rendered even at rest, just hidden. Mounting the SVG and compiling its
   * filter costs a frame, and doing that on the first frame of the transition
   * is a visible hitch exactly as the fire catches.
   */
  return (
    <div className="burn" style={{ visibility: v.live ? 'visible' : 'hidden' }}>
      <BurnArt
        progress={v.burn}
        origin={v.origin}
        mode={v.mode}
        turbulence={options.turbulence}
      />
    </div>
  )
}

export const FilmBurnTransition = createTransition<FilmBurnOptions>({
  timeout: 6000,
  defaults: DEFAULTS,
  overlay: (options) => <BurnOverlay options={options} />,

  setup: () => push?.(REST),

  /**
   * Fire catches, hesitates for a beat, then runs. The pause is what makes the
   * ember readable — a front that races the whole way is over before the eye
   * has resolved any of the detail.
   */
  leave: ({ options, done }) => {
    const origin = options.origin === 'random' ? pickCorner() : options.origin
    const v: State = { burn: 0, mode: 'cover', origin, live: true }
    const tl = gsap.timeline({ onUpdate: () => push?.({ ...v }), onComplete: done })

    tl.to(v, { burn: 0.16, duration: options.burn * 0.3, ease: 'power2.out' })
      .to({}, { duration: options.burn * 0.12 })
      .to(v, { burn: 1, duration: options.burn * 0.72, ease: 'power2.in' })

    tl.timeScale(options.speed)
    return () => tl.kill()
  },

  /**
   * The same fire keeps going and eats the char away, rather than a flash or a
   * fade. Quicker than the burn on purpose: the page catching alight is the
   * part worth watching, and a second long beat is where a transition starts to
   * wear out its welcome.
   */
  enter: ({ options, done }) => {
    const origin = options.origin === 'random' ? pickCorner() : options.origin
    const v: State = { burn: 0, mode: 'clear', origin, live: true }
    const tl = gsap.timeline({
      onUpdate: () => push?.({ ...v }),
      onComplete: () => {
        push?.(REST)
        done()
      },
    })

    tl.to(v, { burn: 1, duration: options.reveal, ease: 'power1.inOut' })

    tl.timeScale(options.speed)
    return () => tl.kill()
  },
})

'use client'

import { TransitionRouter } from 'next-transition-router'
import { useEffect, useRef, type ReactNode } from 'react'

/** Passed to every phase. Query your own nodes out of `overlay`. */
export type TransitionContext<O> = {
  overlay: HTMLDivElement
  /** Whatever the component was given, merged over the config defaults. */
  options: O
  /** Call when the animation is finished. The navigation waits for this. */
  done: () => void
}

/** A phase may return a cleanup function, called if the phase is interrupted. */
export type Phase<O> = (ctx: TransitionContext<O>) => void | (() => void)

export type TransitionConfig<O> = {
  /**
   * Markup that covers the screen. A function when the markup itself depends on
   * the options; otherwise rendered once and reused for every navigation.
   */
  overlay: ReactNode | ((options: O) => ReactNode)
  /** Values a consumer may override as props. */
  defaults: O
  /** Runs once after mount — measure paths, set starting state. */
  setup?: (overlay: HTMLDivElement, options: O) => void
  /** Plays before the route changes. */
  leave: Phase<O>
  /** Plays after the route changes. */
  enter: Phase<O>
  /**
   * Failsafe. If a phase never calls done() the navigation continues anyway,
   * so a broken animation can never trap someone behind an opaque overlay.
   */
  timeout?: number
}

const DEFAULT_TIMEOUT = 4000

const prefersReducedMotion = () =>
  typeof window !== 'undefined' &&
  window.matchMedia('(prefers-reduced-motion: reduce)').matches

/**
 * Turns a transition config into a drop-in provider.
 *
 *   // app/layout.tsx
 *   <CrayonTransition>{children}</CrayonTransition>
 *
 * Engine-agnostic: the phases can use GSAP, Motion, or raw WAAPI. The core only
 * cares that `done()` eventually gets called.
 */
export function createTransition<O extends object>(config: TransitionConfig<O>) {
  const timeout = config.timeout ?? DEFAULT_TIMEOUT

  return function Transition({
    children,
    ...overrides
  }: { children: ReactNode } & Partial<O>) {
    const ref = useRef<HTMLDivElement>(null)
    const options = { ...config.defaults, ...(overrides as Partial<O>) } as O

    // Phases read this rather than closing over a stale render's options.
    const latest = useRef(options)
    latest.current = options

    useEffect(() => {
      if (ref.current) config.setup?.(ref.current, latest.current)
    }, [])

    const run = (phase: Phase<O>) => (next: () => void) => {
      const overlay = ref.current

      // No overlay yet, or the user asked for less motion — navigate straight through.
      if (!overlay || prefersReducedMotion()) {
        next()
        return
      }

      let settled = false
      const done = () => {
        if (settled) return
        settled = true
        clearTimeout(timer)
        next()
      }
      const timer = setTimeout(() => {
        console.warn(`[transition] phase exceeded ${timeout}ms, continuing`)
        done()
      }, timeout)

      let cleanup: void | (() => void)
      try {
        cleanup = phase({ overlay, options: latest.current, done })
      } catch (error) {
        console.error('[transition] phase threw, continuing', error)
        done()
      }

      return () => {
        clearTimeout(timer)
        settled = true
        cleanup?.()
      }
    }

    return (
      <TransitionRouter auto leave={run(config.leave)} enter={run(config.enter)}>
        <div ref={ref} className="transition-overlay" aria-hidden>
          {typeof config.overlay === 'function' ? config.overlay(options) : config.overlay}
        </div>
        {children}
      </TransitionRouter>
    )
  }
}

/* transitions.css — shared styling for every transition in the registry. */

/* ---------- overlay shell (used by all overlay-type transitions) ---------- */

/*
 * inset:0 sizes to the layout viewport, which excludes the scrollbar — so the
 * overlay is centred on the area the reader actually sees. 100vw would include
 * the scrollbar and push the centre to the right of the content instead.
 */
.transition-overlay {
  position: fixed;
  inset: 0;
  z-index: 100;
  pointer-events: none;
}

.transition-overlay svg {
  display: block;
  width: 100%;
  height: 100%;
}

/* ---------- crayon ---------- */

:root {
  --crayon-1: #ff2d87;
  --crayon-2: #aaff00;
  --crayon-3: #0066ff;
}

.crayon {
  position: absolute;
  inset: 0;
  /* Overscaled so strokes drawn near the edges still cover the corners. */
  transform: scale(1.5);
}

/* Hidden until the first leave phase measures the real path lengths. */
.crayon path {
  stroke-dasharray: 99999;
  stroke-dashoffset: 99999;
}

/* ---------- zipper ---------- */

/*
 * Every colour in the artwork reads from these, so overriding them anywhere
 * above the transition recolours the whole zip. Set your own values, or put one
 * of the preset classes below on any ancestor.
 */
:root {
  --zip-metal-hi: #ffffff;
  --zip-metal: #d7d2c8;
  --zip-metal-mid: #8f887c;
  --zip-metal-lo: #4a453e;
  --zip-metal-edge: #211f1c;
  --zip-tape: #3d3d46;
  --zip-tape-lo: #26262c;
}

.zip-steel {
  --zip-metal-hi: #f8fbfe;
  --zip-metal: #c3ced8;
  --zip-metal-mid: #7c8894;
  --zip-metal-lo: #3f4750;
  --zip-metal-edge: #171b20;
  --zip-tape: #2b313a;
  --zip-tape-lo: #191d23;
}

.zip-brass {
  --zip-metal-hi: #fff8dd;
  --zip-metal: #eccb6f;
  --zip-metal-mid: #b8912f;
  --zip-metal-lo: #6b5115;
  --zip-metal-edge: #2b2107;
  --zip-tape: #3a3228;
  --zip-tape-lo: #231f18;
}

.zip-gunmetal {
  --zip-metal-hi: #c6ccd4;
  --zip-metal: #848b95;
  --zip-metal-mid: #4f555d;
  --zip-metal-lo: #2a2d33;
  --zip-metal-edge: #101216;
  --zip-tape: #1f2228;
  --zip-tape-lo: #121418;
}

.zip-copper {
  --zip-metal-hi: #ffe9d6;
  --zip-metal: #e2a179;
  --zip-metal-mid: #a95f37;
  --zip-metal-lo: #5d3018;
  --zip-metal-edge: #23110a;
  --zip-tape: #332822;
  --zip-tape-lo: #1d1714;
}

.zip-rig {
  position: relative;
  height: 100%;
  width: 100%;
  overflow: hidden;
}

.zip-panel {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 50%;
}

.zip-band {
  position: absolute;
  width: 100%;
  overflow: hidden;
}

.zip-band-art {
  position: absolute;
}

.zip-slider-layer {
  position: absolute;
  inset: 0;
  height: 100%;
  width: 100%;
  pointer-events: none;
}

.zip-fill {
  height: 100%;
  width: 100%;
}

@media (prefers-reduced-motion: reduce) {
  .zip-rig { display: none }
}

/* ---------- film burn ---------- */

:root {
  --burn-core: #fff4dc;
  --burn-hot: #ffb32e;
  --burn-mid: #d94a12;
  --burn-edge: #6b1806;
  --burn-char: #0a0705;
  --burn-soot: #1e1008;
  --burn-lamp: #fff1d0;
}

.burn {
  position: absolute;
  inset: 0;
  /* the filter is expensive to rasterise; keep it on its own layer */
  will-change: opacity;
}

.burn-fill {
  position: absolute;
  inset: 0;
  height: 100%;
  width: 100%;
}


@media (prefers-reduced-motion: reduce) {
  .burn { display: none }
}
